using Builder.Core;
using System.Collections.Immutable;
using System.Security.Cryptography;
using System.Text.Json;

internal static class SurfaceBrushChecks
{
    public static async Task Run(string root,string? evidenceRoot=null)
    {
        var output=evidenceRoot??Path.Combine(root,".local/evidence/surface-brush-20261022/core");Directory.CreateDirectory(output);var inputs=Path.Combine(root,".local/fixtures/surface-brush");var cases=new List<string>();var outputs=new List<object>();
        var red=new SurfaceMaterial("Brush red",new(214,82,72));var blue=new SurfaceMaterial("Brush blue",new(38,124,181));
        async Task<EditorSession> Load(string name){var s=new EditorSession();Ok(await s.OpenAsync(Path.Combine(inputs,name+".3mf")));return s;}
        SurfaceBrushSample Top(double x,double y)=>new(new(x,y,60),new(0,0,-1));
        SurfaceBrushStroke Stroke(double d,SurfaceMaterial? material,params SurfaceBrushSample[] samples)=>new(d,material,samples.ToImmutableArray());
        void Pass(string name){cases.Add(name);Console.WriteLine("PASS "+name);}
        async Task Save(EditorSession session,string filename,SurfaceBrushRequest request,string expected)
        {
            var path=Path.Combine(output,filename);Ok(await session.SaveAsync(path));using var reader=new EditorSession();Ok(await reader.OpenAsync(path));Check(reader.Snapshot.Scene.Objects.Length==session.Snapshot.Scene.Objects.Length&&reader.Snapshot.Scene.Groups.Length==session.Snapshot.Scene.Groups.Length,"Brush save lost ownership.");
            for(var i=0;i<reader.Snapshot.Scene.Objects.Length;i++){var a=session.Snapshot.Scene.Objects[i];var b=reader.Snapshot.Scene.Objects[i];Check(a.Material==b.Material&&a.TriangleMaterials.OrderBy(p=>p.Key).SequenceEqual(b.TriangleMaterials.OrderBy(p=>p.Key))&&a.Transform==b.Transform,"Brush map/material/transform persistence failed.");}
            outputs.Add(new{path=filename,sha256=Hash(path),request,expected,objects=session.Snapshot.Scene.Objects.Select(o=>new{o.Name,o.Material,overrides=o.TriangleMaterials.OrderBy(p=>p.Key).Select(p=>new{triangleIndex=p.Key,material=p.Value})})});
        }
        using(var session=await Load("dense-cube"))
        {
            var before=session.Snapshot;var obj=before.Scene.Objects.Single();var first=Stroke(4,red,Top(5.3,5.7));var second=Stroke(2,blue,Top(15.3,14.7));var request=new SurfaceBrushRequest(obj.Id,[first]);
            Ok(await session.PreviewAsync(request));var p=session.Snapshot.Preview!;var redIndices=p.SurfaceBrush!.TriangleIndices;Check(redIndices.Length>1&&redIndices.Length<100&&redIndices.All(i=>i>=200&&i<400),"Local brush flooded top/back faces.");Check(p.SurfaceBrush.SampleCount==1&&p.SelectedObjectIds.SequenceEqual(before.SelectedObjectIds),"Brush metadata/selection wrong.");
            Ok(await session.PreviewSurfaceBrushAsync(request with{Strokes=[Stroke(10,red,Top(5.3,5.7))]},p.Id));var wider=session.Snapshot.Preview!;Check(wider.SurfaceBrush!.TriangleIndices.Length>redIndices.Length,"Diameter did not change coverage.");
            var accumulated=request with{Strokes=[first,second]};Ok(await session.PreviewSurfaceBrushAsync(accumulated,wider.Id));p=session.Snapshot.Preview!;Check(p.Scene.Objects[0].TriangleMaterials.Count>redIndices.Length&&redIndices.All(i=>p.Scene.Objects[0].GetTriangleMaterial(i)==red),"Accumulated stroke lost its own material/diameter.");Check(p.Scene.Objects[0].TriangleMaterials.Values.Contains(blue),"Second color missing.");Ownership(p.Scene,before.Scene,obj.Id);Check(ReferenceEquals(session.Snapshot.Scene,before.Scene),"Preview changed accepted scene.");
            Apply(session);var accepted=session.Snapshot.Scene;await Save(session,"two-color-brush.3mf",accumulated,"Two independent localized top marks; first4mm red, second2mm blue, whole triangle approximation; no bottom/back colors");Ok(session.Undo());Check(ReferenceEquals(session.Snapshot.Scene,before.Scene),"One Undo did not restore exact original.");Ok(session.Redo());Check(ReferenceEquals(session.Snapshot.Scene,accepted),"Redo changed material ownership.");
            Ok(await session.PreviewSurfaceBrushAsync(new(obj.Id,[Stroke(4,null,Top(5.3,5.7))])));p=session.Snapshot.Preview!;Check(redIndices.All(i=>!p.Scene.Objects[0].TriangleMaterials.ContainsKey(i))&&p.Scene.Objects[0].TriangleMaterials.Values.Contains(blue),"Clear removed unrelated color or failed fallback.");Check(session.DiscardPreview(p.Id).Outcome==Outcome.Cancelled,"Clear discard failed.");
        }
        using(var alias=new EditorSession())
        {
            Ok(await alias.OpenAsync(Path.Combine(root,"fixtures/generated/cube-20mm.stl")));var id=alias.Snapshot.SelectedObjectId!.Value;Ok(await alias.PreviewSurfaceBrushAsync(new(id,[Stroke(.001,red,Top(9,9.3))])));var small=alias.Snapshot.Preview!;Check(small.SurfaceBrush!.TriangleIndices.Length>=1&&small.SurfaceBrush.TriangleIndices.All(i=>{var t=small.Scene.Objects[0].Mesh.Triangles[i];return small.Scene.Objects[0].Mesh.Vertices[t.A].Z==20;}),"Visible seed or exact-coordinate STL adjacency failed.");Check(small.Scene.Objects[0].Material==SurfaceMaterial.Neutral,"Unassigned brush failed explicit neutral promotion.");
        }
        Pass("Local physical diameter, visible seed, exact STL aliases and ordered multi-color stroke replay preserve geometry/selection; clear, one-step history and3MF persist exact face maps");
        using(var shell=await Load("sealed-shell"))
        {
            var id=shell.Snapshot.SelectedObjectId!.Value;var before=shell.Snapshot;Ok(await shell.PreviewSurfaceBrushAsync(new(id,[Stroke(100,red,Top(10,10))])));var p=shell.Snapshot.Preview!;File.WriteAllText(Path.Combine(output,"shell-coverage-diagnostic.json"),JsonSerializer.Serialize(new{count=p.SurfaceBrush!.TriangleIndices.Length,unexpected=p.SurfaceBrush.TriangleIndices.Where(i=>i<200||i>=400).Select(i=>new{triangleIndex=i,triangle=p.Scene.Objects[0].Mesh.Triangles[i]})},new JsonSerializerOptions{WriteIndented=true}));Check(p.SurfaceBrush!.TriangleIndices.Length>10&&p.SurfaceBrush.TriangleIndices.All(i=>i>=200&&i<400),"Outside brush crossed to cavity/bottom/back surfaces.");Ownership(p.Scene,before.Scene,id);Check(shell.DiscardPreview(p.Id).Outcome==Outcome.Cancelled,"Shell discard failed.");
            var inside=new SurfaceBrushSample(new(10,10,10),new(0,0,1));Ok(await shell.PreviewSurfaceBrushAsync(new(id,[Stroke(4,blue,inside)])));p=shell.Snapshot.Preview!;Check(p.SurfaceBrush!.TriangleIndices.All(i=>i>=1400&&i<1600),"Two-sided inverted inner winding failed or crossed shell.");Check(shell.DiscardPreview(p.Id).Outcome==Outcome.Cancelled,"Inner discard failed.");
            Ok(shell.Execute(new AddPrimitive(PrimitiveKind.Cube,new(4,4,2))));var blocker=shell.Snapshot.SelectedObjectId!.Value;Ok(shell.Execute(new MoveObject(blocker,new(14,10,24))));before=shell.Snapshot;
            Ok(await shell.PreviewSurfaceBrushAsync(new(id,[Stroke(20,red,Top(6,10))])));p=shell.Snapshot.Preview!;var mesh=before.Scene.Objects.Single(o=>o.Id==id).Mesh;
            var hidden=Enumerable.Range(200,200).Where(i=>{var t=mesh.Triangles[i];var c=(mesh.Vertices[t.A]+mesh.Vertices[t.B]+mesh.Vertices[t.C])*(1d/3);return c.X>13&&c.X<15&&c.Y>9&&c.Y<11;}).ToArray();Check(hidden.Length>0&&hidden.All(i=>!p.SurfaceBrush!.TriangleIndices.Contains(i)),"Other-object centroid occlusion leaked.");Check(shell.DiscardPreview(p.Id).Outcome==Outcome.Cancelled,"Occlusion discard failed.");
            Check((await shell.PreviewSurfaceBrushAsync(new(id,[Stroke(20,red,Top(14,10))]))).Outcome==Outcome.Invalid,"Nearest other-object hit painted through occluder.");Same(shell,before);
        }
        Pass("Full-scene two-sided visibility blocks front occluders and closed/cavity backs; a ray inside a cavity can paint its visible inward-wound surface without crossing shells");
        using(var member=await Load("dense-pair"))
        {
            var group=member.Snapshot.Scene.Groups.Single();var id=group.ObjectIds[0];var request=new SurfaceBrushRequest(id,[Stroke(4,red,Top(6,7))]);var before=member.Snapshot;Check((await member.PreviewSurfaceBrushAsync(request)).Outcome==Outcome.Invalid,"Root grouped leaf brush accepted.");Same(member,before);Ok(member.EnterGroup(group.Id,id));request=request with{MemberGroupId=group.Id};before=member.Snapshot;Ok(await member.PreviewSurfaceBrushAsync(request));var p=member.Snapshot.Preview!;Ownership(p.Scene,before.Scene,id);Check(p.SelectedObjectIds.SequenceEqual(before.SelectedObjectIds)&&p.EditingGroupId==group.Id,"Member brush changed selection/scope.");Apply(member);await Save(member,"member-brush.3mf",request,"Localized red stroke on first white member; blue companion/group/geometry retained");Ok(member.Undo());Check(ReferenceEquals(member.Snapshot.Scene,before.Scene),"Member brush Undo not exact.");Ok(member.ExitGroup());
            Ok(member.Execute(new AddPrimitive(PrimitiveKind.Cube,new(4,4,2))));var blocker=member.Snapshot.SelectedObjectId!.Value;Ok(member.Execute(new MoveObject(blocker,new(6,7,24))));Ok(member.EnterGroup(group.Id,id));before=member.Snapshot;
            Check((await member.PreviewSurfaceBrushAsync(request)).Outcome==Outcome.Invalid,"Outside-scope object did not occlude member brush.");Same(member,before);Check((await member.PreviewSurfaceBrushAsync(request with{MemberGroupId=null})).Outcome==Outcome.Conflict,"Brush borrowed member authority.");Same(member,before);
        }
        Pass("One member requires explicit scope; group/companion/material refs and selection persist, while outside-scope objects remain occluders and native save retains ownership");
        using(var session=await Load("dense-cube"))
        {
            var id=session.Snapshot.SelectedObjectId!.Value;Ok(session.Execute(new RenameObject(id,"Temporary")));Ok(session.Undo());var before=session.Snapshot;var sample=Top(5.3,5.7);var first=Stroke(4,red,sample);var request=new SurfaceBrushRequest(id,[first]);
            Ok(await session.PreviewSurfaceBrushAsync(new(id,[first,Stroke(4,null,sample)])));Check(ReferenceEquals(session.Snapshot.Preview!.Scene,before.Scene),"Paint/clear replay failed exact final-state no-op.");Apply(session);Same(session,before);
            Ok(await session.PreviewSurfaceBrushAsync(request));var firstToken=session.Snapshot.Preview!.Id;Ok(await session.PreviewSurfaceBrushAsync(request with{Strokes=[first,Stroke(2,blue,Top(15,15))]},firstToken));var held=session.Snapshot;
            Check(held.Preview!.Id!=firstToken,"Brush replacement reused token.");Check((await session.PreviewSurfaceBrushAsync(request,firstToken)).Outcome==Outcome.Conflict,"Stale brush accepted.");Same(session,held);Check((await session.PreviewSurfaceBrushAsync(request,held.Preview.Id,expectedRevision:before.Revision-1)).Outcome==Outcome.Conflict,"Stale revision accepted.");Same(session,held);Check((await session.PreviewSurfaceBrushAsync(request with{ObjectId=Guid.NewGuid()},held.Preview.Id)).Outcome==Outcome.Conflict,"Replacement changed target.");Same(session,held);
            foreach(var invalid in new[]{request with{Strokes=[]},request with{Strokes=[first with{DiameterMillimeters=0}]},request with{Strokes=[first with{Samples=[sample with{Direction=new()}]}]},request with{Strokes=[first with{Samples=[sample with{MinimumDistance=10,MaximumDistance=2}]}]},request with{Strokes=[first with{Samples=[Top(100,100)]}]},request with{Strokes=Enumerable.Repeat(first,129).ToImmutableArray()},request with{Strokes=Enumerable.Repeat(first with{Samples=Enumerable.Repeat(sample,4096).ToImmutableArray()},3).ToImmutableArray()}})
            {Check((await session.PreviewSurfaceBrushAsync(invalid,held.Preview.Id)).Outcome==Outcome.Invalid,"Invalid/missed brush replaced candidate.");Same(session,held);}
            foreach(var stage in new[]{"Preparing brush connectivity","Painting brush samples","Ready to preview surface brush"}){using var ct=new CancellationTokenSource();Check((await session.PreviewSurfaceBrushAsync(request,held.Preview.Id,ct.Token,new Progress(p=>{if(p.Stage==stage)ct.Cancel();}))).Outcome==Outcome.Cancelled,"Brush cancel failed at "+stage);Same(session,held);}
            using(var entered=new ManualResetEventSlim())using(var release=new ManualResetEventSlim())using(var ct=new CancellationTokenSource())
            {var task=session.PreviewSurfaceBrushAsync(request,held.Preview.Id,ct.Token,new Progress(p=>{if(p.Stage=="Painting brush samples"){entered.Set();Check(release.Wait(10000),"Brush barrier timeout.");}}));Check(entered.Wait(10000),"Brush barrier not reached.");Check(session.Select(null).Outcome==Outcome.Busy&&session.ApplyPreview(held.Preview.Id).Outcome==Outcome.Busy,"Brush busy guard failed.");ct.Cancel();release.Set();Check((await task).Outcome==Outcome.Cancelled,"Busy brush cancel failed.");Same(session,held);}
            Apply(session);Check(session.Snapshot.Revision==before.Revision+1&&session.Snapshot.FilePath==before.FilePath&&!session.Snapshot.CanRedo,"Brush Apply history/path failed.");Ok(session.Undo());Check(ReferenceEquals(session.Snapshot.Scene,before.Scene)&&!session.Snapshot.IsDirty,"Brush Undo lost clean scene.");Ok(await session.PreviewSurfaceMaterialAsync(new(id,200,blue)));var foreign=session.Snapshot;Check((await session.PreviewSurfaceBrushAsync(request,foreign.Preview!.Id)).Outcome==Outcome.Conflict,"Brush replaced different tool candidate.");Same(session,foreign);
        }
        Pass("Exact final-state no-op preserves Redo; same-target fresh-token replacement, invalid/budget/miss/stale/foreign failures and busy/cancellation retain prior candidate and accepted work");
        File.WriteAllText(Path.Combine(output,"surface-brush-results.json"),JsonSerializer.Serialize(new{timestamp=DateTimeOffset.UtcNow,scenarioCount=cases.Count,cases,outputs,runtime=System.Runtime.InteropServices.RuntimeInformation.FrameworkDescription,core=new{path=typeof(EditorSession).Assembly.Location,sha256=Hash(typeof(EditorSession).Assembly.Location)},inputs=Directory.GetFiles(inputs,"*.3mf").Select(p=>new{path=p,sha256=Hash(p)}),limitations="Whole triangles intersecting edge-connected brush sphere; centroid line-of-sight approximation, visible seed always retained. No texture/partial-face raster painting or interpolation between ray samples. Other shells do not flood through volume. No UI/native claim."},new JsonSerializerOptions{WriteIndented=true,NumberHandling=System.Text.Json.Serialization.JsonNumberHandling.AllowNamedFloatingPointLiterals}));Console.WriteLine($"{cases.Count} surface brush groups passed. Evidence: {output}");
    }
    private static void Ownership(Scene after,Scene before,Guid target)
    {Check(after.Groups==before.Groups&&after.Metadata==before.Metadata,"Brush changed group/metadata.");foreach(var obj in before.Objects){var next=after.Objects.Single(o=>o.Id==obj.Id);Check(next.Name==obj.Name&&next.Transform==obj.Transform&&ReferenceEquals(next.Mesh,obj.Mesh),"Brush changed geometry/identity.");if(obj.Id!=target)Check(ReferenceEquals(obj,next),"Brush changed another object.");}}
    private static void Apply(EditorSession s)=>Ok(s.ApplyPreview(s.Snapshot.Preview!.Id));
    private static void Same(EditorSession s,EditorSnapshot before)=>Check(s.Snapshot==before,"Brush changed accepted/prior preview state.");
    private static void Check(bool value,string message){if(!value)throw new Exception(message);}
    private static void Ok(OperationResult result)=>Check(result.Succeeded,result.ToString());
    private sealed class Progress(Action<OperationProgress> action):IProgress<OperationProgress>{public void Report(OperationProgress p)=>action(p);}
    private static string Hash(string path)=>Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(path)));
}
